<main class="write-main"><header><h1><?=e($definition['name'])?> connection</h1><p><a href="<?=url('/write/connections#integrations-'.(in_array($provider,['openai','gemini'],true)?'ai':'finance'))?>">Back to integrations</a></p></header>
<?php foreach(flashes()as$f):?><p class="notice" role="status"><?=e($f['message'])?></p><?php endforeach;?><?php if($error):?><p class="notice error" role="alert"><?=e($error)?></p><?php endif;?><?php if($check):?><p class="notice" role="status"><?=e($check)?></p><?php endif;?>
<section class="settings-card"><h2>Connect <?=e($definition['name'])?></h2><p>Use this service’s application credentials. Never enter a banking, social-account or email password. Saved secrets are encrypted and are not displayed. Blank secret fields retain existing values. Only this provider’s settings are changed.</p>
<form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save">
<?php if($definition['environment']):?><label>Environment<select name="environment"><option value="sandbox" <?=setting($definition['prefix'].'.environment','sandbox')==='sandbox'?'selected':''?>>Sandbox</option><option value="live" <?=setting($definition['prefix'].'.environment','sandbox')==='live'?'selected':''?>>Live</option></select></label><?php endif;?>
<?php foreach($definition['secrets']as$key=>$label):?><div class="field"><label for="integration-<?=e($key)?>"><?=e($label)?> <?=setting($definition['prefix'].'.'.$key,'')!==''?'· saved':''?></label><input id="integration-<?=e($key)?>" type="password" name="<?=e($key)?>" autocomplete="new-password" maxlength="5000" placeholder="Leave blank to retain saved value"></div><?php endforeach;?>
<?php foreach($definition['fields']as$key=>$label):?><div class="field"><label for="integration-<?=e($key)?>"><?=e($label)?></label><?php if($key==='transaction_type'):?><select id="integration-<?=e($key)?>" name="<?=e($key)?>"><?php foreach(['CustomerPayBillOnline'=>'PayBill','CustomerBuyGoodsOnline'=>'Buy Goods']as$value=>$name):?><option value="<?=e($value)?>" <?=setting('mpesa.transaction_type','CustomerPayBillOnline')===$value?'selected':''?>><?=e($name)?></option><?php endforeach;?></select><?php else:?><input id="integration-<?=e($key)?>" name="<?=e($key)?>" maxlength="240" value="<?=e(setting($definition['prefix'].'.'.$key,$definition['defaults'][$key]??''))?>"><?php endif;?></div><?php endforeach;?>
<button class="wbtn primary">Save connection setup</button></form>
<?php if(in_array($provider,['mpesa','pesapal','paypal'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="verify"><button class="wbtn" <?=!integration_hub_configured($provider)?'disabled':''?>>Verify authentication · no payment</button></form><p>Authentication verifies credentials only. Receiving rights and payment confirmation still require provider approval and callbacks. No payment is started by this check.</p><?php endif;?>
<?php if($provider==='pesapal'):?><p><a href="<?=url('/write/settings')?>">Manage the registered Pesapal IPN</a></p><?php endif;?></section>
<?php if($provider==='paypal'):$notice=paypal_notifications_config();$active=paypal_notifications_current($notice);$last=comm_get('paypal.notification.last');?><section class="settings-card"><h2>Automatic payment updates</h2><p>Register the exact URL below in this PayPal app. Select the events listed here. This receiver verifies each signature through PayPal and matches only known website orders. Payments are confirmed by an independent read-only order check.</p><div class="field"><label>Callback URL</label><code><?=e(url('/webhooks/paypal'))?></code></div><ul><?php foreach(paypal_notification_types()as$type):?><li><code><?=e($type)?></code></li><?php endforeach;?></ul>
<form method="post"><?=csrf_field()?><input type="hidden" name="action" value="paypal_notifications"><input type="hidden" name="notification_version" value="<?=(int)($notice['version']??0)?>"><div class="field"><label for="paypal-webhook-id">PayPal webhook ID</label><input id="paypal-webhook-id" name="webhook_id" maxlength="80" value="<?=e($notice['webhook_id']??'')?>"></div><label class="check"><input type="checkbox" name="notifications_enabled" value="1" <?=$active&&!empty($notice['enabled'])?'checked':''?>>Receive verified payment notifications</label><label class="check"><input type="checkbox" name="reconcile_enabled" value="1" <?=$active&&!empty($notice['reconcile'])?'checked':''?>>Automatically check new PayPal payments against provider records</label><p>Applies to PayPal contributions created from activation onward. No automatic captures, payouts, refunds or emails. Refund and reversal notices are held for review.</p><button class="wbtn primary">Verify & save payment updates</button></form><p>Receiver: <strong><?=$active&&!empty($notice['enabled'])?'Enabled':'Off'?></strong> · Automatic checks: <strong><?=$active&&!empty($notice['reconcile'])?'Enabled':'Off'?></strong></p><?php if($last):?><p>Last verified notification: <?=e($last['event_type']??'')?> · <?=e((new DateTimeImmutable('@'.(int)$last['at']))->setTimezone(comm_zone('Africa/Nairobi'))->format('j M Y H:i'))?> EAT</p><?php else:?><p>No verified PayPal notification has been received yet.</p><?php endif;?><p>Changing API credentials or environment switches these features off until authentication and notification settings are verified again.</p><p><a class="wbtn" href="<?=url('/write/monthly-support')?>">Manage monthly support plans</a></p></section><?php endif;?></main>
